  `fecha_atendido` datetime DEFAULT NULL,
  `fecha_devuelto` datetime DEFAULT NULL,
  PRIMARY KEY (`id_orden`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1055 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_spanish2_ci ROW_FORMAT=DYNAMIC;
