DROP TABLE IF EXISTS `productos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `productos` (
  `id_producto` int NOT NULL AUTO_INCREMENT,
  `id_bodega` int NOT NULL,
  `id_unidad_medida` int DEFAULT NULL,
  `nombre_producto` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_spanish2_ci NOT NULL,
  `estado_producto` tinyint(1) NOT NULL,
  `log_producto` text CHARACTER SET utf8mb3 COLLATE utf8mb3_spanish2_ci,
  `id_partida` int DEFAULT NULL,
  `codigo` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_spanish2_ci DEFAULT NULL,
  PRIMARY KEY (`id_producto`) USING BTREE,
  KEY `fk_productos_unidades_medida1_idx` (`id_unidad_medida`) USING BTREE,
  KEY `fk_productos_bodegas1_idx` (`id_bodega`) USING BTREE,
  KEY `fk_productos_partida1_idx` (`id_partida`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5334 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_spanish2_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

